#include "display_filters.h"

#include <cmath>
#include <cstddef>

namespace nds_display_filter {
namespace {

// One gamma curve per mode, indexed by kColorMode*. Mode 0 states its exponent
// explicitly even though it is the identity: the table is generated by one
// formula, and a special case would let the identity drift away from 0->0 and
// 255->255 unnoticed.
//
// The curve brightens as the exponent rises, which is the direction the DS's
// "colour reproduction" options go: 1.0 (raw), 1.1, 1.2, 1.4.
constexpr double kExponents[kColorModeCount] = {1.0, 1.1, 1.2, 1.4};

constexpr int kChannelMax = 255;

// The channel curve: out = round(255 * pow(in / 255, 1 / exponent)).
//
// Doubles are exact enough here: the closest any value in the whole table comes
// to a .5 tie is 6.9e-4 (mode 3, in = 49), so no rounding mode choice can flip
// an entry. std::lround is still used rather than a cast so the intent is
// explicit, and the clamp keeps a hypothetical NaN or overshoot from wrapping.
uint8_t curve_value(int channel, double exponent) {
    if (exponent == 1.0) return static_cast<uint8_t>(channel);
    const double normalised = static_cast<double>(channel) / kChannelMax;
    const double curved = kChannelMax * std::pow(normalised, 1.0 / exponent);
    const long rounded = std::lround(curved);
    if (rounded < 0) return 0;
    if (rounded > kChannelMax) return static_cast<uint8_t>(kChannelMax);
    return static_cast<uint8_t>(rounded);
}

int exponent_index(int color_mode) {
    return color_mode_is_valid(color_mode) ? color_mode : kColorModeOriginal;
}

}  // namespace

const char* color_mode_name(int mode) {
    switch (mode) {
        case kColorModeOriginal: return "Original";
        case kColorModeLight: return "Light";
        case kColorModeModerate: return "Moderate";
        case kColorModeStrong: return "Strong";
        default: return "";
    }
}

bool color_mode_is_valid(int mode) {
    return mode >= 0 && mode < kColorModeCount;
}

void build_lut(int color_mode, uint8_t lut[256]) {
    // Null is a programming error, not something to report: the contract has no
    // failure arm, so the call is a no-op rather than a crash.
    if (lut == nullptr) return;
    const double exponent = kExponents[exponent_index(color_mode)];
    for (int channel = 0; channel < 256; ++channel) {
        lut[channel] = curve_value(channel, exponent);
    }
}

bool lut_is_identity(const uint8_t lut[256]) {
    // A null table carries no curve, so it is treated as the identity: the
    // caller's fast path then simply skips a pass it could not have built.
    if (lut == nullptr) return true;
    for (int channel = 0; channel < 256; ++channel) {
        if (lut[channel] != static_cast<uint8_t>(channel)) return false;
    }
    return true;
}

bool apply(const uint32_t* in, uint32_t* out, int width, int height,
           int pitch_pixels, int color_mode, bool lcd_grid) {
    if (in == nullptr || out == nullptr) return false;
    if (width <= 0 || height <= 0) return false;
    if (pitch_pixels < width) return false;

    uint8_t lut[256];
    build_lut(color_mode, lut);
    // Mode 0 (and an invalid mode) with the grid off is a pure copy; skip the
    // per-channel table lookups for it rather than reading a table we know.
    const bool curve = !lut_is_identity(lut);

    for (int y = 0; y < height; ++y) {
        const uint32_t* source_row =
            in + static_cast<std::ptrdiff_t>(y) * pitch_pixels;
        uint32_t* target_row =
            out + static_cast<std::ptrdiff_t>(y) * pitch_pixels;
        // Row parity is constant across the row, so the "odd row" half of the
        // grid test is hoisted out of the x loop.
        const bool dim_row = lcd_grid && ((y & 1) != 0);
        for (int x = 0; x < width; ++x) {
            const uint32_t pixel = source_row[x];
            const uint32_t alpha = pixel & 0xFF000000u;
            int red = static_cast<int>((pixel >> 16) & 0xFFu);
            int green = static_cast<int>((pixel >> 8) & 0xFFu);
            int blue = static_cast<int>(pixel & 0xFFu);

            // Colour reproduction first, then the grid: the grid models the
            // panel's coverage of an already-reproduced picture, so dimming a
            // post-curve value is the physical order.
            if (curve) {
                red = lut[red];
                green = lut[green];
                blue = lut[blue];
            }

            // The grid covers one column in two and one row in two, so a pixel
            // is dimmed when EITHER coordinate is odd. 0.75 is applied as
            // (v * 3 + 2) / 4, which is round-half-up of 0.75 * v in integer
            // math: v = 2 gives 2, v = 10 gives 8, and the result is exact for
            // every 8-bit input without touching floating point per pixel.
            if (dim_row || (lcd_grid && ((x & 1) != 0))) {
                red = (red * 3 + 2) / 4;
                green = (green * 3 + 2) / 4;
                blue = (blue * 3 + 2) / 4;
            }

            target_row[x] = alpha |
                            (static_cast<uint32_t>(red) << 16) |
                            (static_cast<uint32_t>(green) << 8) |
                            static_cast<uint32_t>(blue);
        }
    }
    return true;
}

}  // namespace nds_display_filter
